#include <iostream.h>
#include <conio.h>

int main()
{
  double x, y;
  cout << "Введите координату x точки M (x , y)" << endl << "- > ";
  cin >> x;
  cout << "Введите координату y точки M (x , y)" << endl << "- > ";
  cin >> y;
  cout << endl;
  if (x == 0 && y == 0)
    cout << "Точка M (" << x << ", " << y << ") находится в начале координат." << endl;
  else if (x == 0)
    cout << "Точка M (" << x << ", " << y << ") лежит на оси Y." << endl;
  else if (y == 0)
    cout << "Точка M (" << x << ", " << y << ") лежит на оси X." << endl;
  else if (x > 0 && y > 0)
    cout << "Точка M (" << x << ", " << y << ") находится в I квадранте декартовой плоскости." << endl;
  else if (x < 0 && y > 0)
    cout << "Точка M (" << x << ", " << y << ") находится в II квадранте декартовой плоскости." << endl;
  else if (x < 0 && y < 0)
    cout << "Точка M (" << x << ", " << y << ") находится в III квадранте декартовой плоскости." << endl;
  else
    cout << "Точка M (" << x << ", " << y << ") находится в IV квадранте декартовой плоскости." << endl;
  getch();
  return 0;
}

#include <iostream.h>
#include <conio.h>

int main()
{
  double x, y, s, p;
  cout << "Введите число X" << endl << "- > ";
  cin >> x;
  cout << "Введите число Y" << endl << "- > ";
  cin >> y;
  s = (x + y) / 2;      // полусумма
  p = 2 * x * y;        // удвоенное произведение
  if (x < y)
  {
    x = s;
    y = p;
  }
  else
  {
    y = s;
    x = p;
  }
  cout << endl << "X = " << x << endl << "Y = " << y << endl;
  getch();
  return 0;
}

#include <iostream.h>
#include <conio.h>

int main()
{
  double x, y;
  cout << "Введите число X" << endl << "- > ";
  cin >> x;
  if (x > 0 && x < 2)
    y = x * x;
  else if (x > -2 && x <= 0)
    y = x + 4;
  else
    y = 0;
  cout << endl;
  cout << "                         -" << endl;
  cout << "                        / x*x, если 0<x<2" << endl;
  cout << "Значение функции y = ++ x+4, если -2<x<=0" << endl;
  cout << "                        \\ 0, во всех остальных случаях" << endl;
  cout << "                         -" << endl;
  cout << "Y = " << y << endl;
  getch();
  return 0;
}

