#include <iostream.h>
#include <conio.h>

int main()
{
  double a, b;
  char op;
  cout << "Введите выражение (например 5 * 3): ";
  cin >> a >> op >> b;
  switch (op)
  {
    case '+': cout << "= " << a + b << endl; break;
    case '-': cout << "= " << a - b << endl; break;
    case '*': cout << "= " << a * b << endl; break;
    case '/':
      if (b == 0) cout << "Делить на 0 нельзя" << endl;
      else cout << "= " << a / b << endl;
      break;
    default: cout << "Неизвестная операция " << op << endl;
  }
  getch();
  return 0;
}

