int NOD2(int a, int b)
{
  while (a != 0)          // НОД(A,B) = НОД(B mod A, A)
  {
    int t = b % a;
    b = a;
    a = t;
  }
  return b;               // НОД(0,B) = B
}

int main()
{
  int a, b, c, d;
  cout << "Введи 1-е число: -> "; cin >> a;
  cout << "Введи 2-е число: -> "; cin >> b;
  cout << "Введи 3-е число: -> "; cin >> c;
  cout << "Введи 4-е число: -> "; cin >> d;
  cout << "НОД чисел " << a << " и " << b << " равен: " << NOD2(a, b) << endl;
  cout << "НОД чисел " << a << " и " << c << " равен: " << NOD2(a, c) << endl;
  cout << "НОД чисел " << a << " и " << d << " равен: " << NOD2(a, d) << endl;
  getch();
  return 0;
}

#include <iostream.h>
#include <conio.h>

int NOD2(int a, int b)
{
  while (a != 0) { int t = b % a; b = a; a = t; }
  return b;
}

void Frac(int a, int b, int &p, int &q)   // p и q — по ссылке: это результаты
{
  int d = NOD2(a < 0 ? -a : a, b < 0 ? -b : b);
  p = a / d;
  q = b / d;
  if (q < 0) { p = -p; q = -q; }         // знак — в числитель
}

int main()
{
  int a, b, c, d, e, f, g, h, p, q;
  cout << "a/b: "; cin >> a >> b;
  cout << "c/d: "; cin >> c >> d;
  cout << "e/f: "; cin >> e >> f;
  cout << "g/h: "; cin >> g >> h;
  Frac(a * d + c * b, b * d, p, q);
  cout << a << "/" << b << " + " << c << "/" << d << " = " << p << "/" << q << endl;
  Frac(a * f + e * b, b * f, p, q);
  cout << a << "/" << b << " + " << e << "/" << f << " = " << p << "/" << q << endl;
  Frac(a * h + g * b, b * h, p, q);
  cout << a << "/" << b << " + " << g << "/" << h << " = " << p << "/" << q << endl;
  getch();
  return 0;
}

