long fact(int n)
{
  if (n <= 1) return 1;
  return n * fact(n - 1);
}

double power(double x, int n)
{
  if (n == 0) return 1;
  return x * power(x, n - 1);
}

int digitSum(int n)
{
  if (n < 10) return n;
  return n % 10 + digitSum(n / 10);
}

