  cout << "10! = " << fact(10) << endl;
  cout << "2^10 = " << power(2, 10) << endl;
  cout << "1.5^3 = " << power(1.5, 3) << endl;
  cout << "Сумма цифр 98765 = " << digitSum(98765) << endl;
  getch();
  return 0;
}

