class Shape
{
public:
  virtual double area() = 0;               // чисто виртуальный: Shape — абстрактный
  virtual const char* name() = 0;
  virtual ~Shape() {}
};

class Circle : public Shape
{
  double r;
public:
  Circle(double r0) { r = r0; }
  double area() { return M_PI * r * r; }
  const char* name() { return "Круг"; }
};

