{
protected:
  double w, h;
public:
  Rect(double a, double b) { w = a; h = b; }
  double area() { return w * h; }
  const char* name() { return "Прямоугольник"; }
};

class Square : public Rect                 // наследник наследника
{
public:
  Square(double a) : Rect(a, a) {}
  const char* name() { return "Квадрат"; }
};

