  cout << "Высота: "; cin >> h;
  r.Width = w;
  r.Height = h;
  cout << "Width = " << r.Width << ", Height = " << r.Height << endl;
  cout << "Area = " << r.Area << ", Perimeter = " << r.Perimeter << endl;
  getch();
  return 0;
}

