    int ind = Application->MessageBox("Do you want to save a file?", "Save", MB_YESNOCANCEL);
    if (ind == IDYES) { Save1Click(Sender); Memo1->Clear(); StatusBar1->Panels->Items[0]->Text = "NoName"; }
    else if (ind == IDNO) { Memo1->Clear(); StatusBar1->Panels->Items[0]->Text = "NoName"; }
    else return;
  }
}
//---------------------------------------------------------------------------
void __fastcall TForm1::DateTime1Click(TObject *Sender)
{
  Memo1->Lines->Add(DateTimePicker1->DateTime.DateString() + " " + Now().TimeString());
}
//---------------------------------------------------------------------------
void __fastcall TForm1::Exit1Click(TObject *Sender)
{
  if (Memo1->Lines->Count > 0 && Application->MessageBox("Save the text?", "Exit", MB_YESNO) == IDYES)
    Save1Click(Sender);
  Close();
}
//---------------------------------------------------------------------------
void __fastcall TForm1::About1Click(TObject *Sender)
{
  ShowMessage("Текстовый редактор. Автор: студент группы ...");
}
